#!/usr/bin/env python3
"""Inline each page's critical CSS and load the full stylesheet without blocking. Run by build.sh.

Every page that uses the site stylesheet gets, in place of the old fully inlined <style> block (or a
<link rel="stylesheet" href="/css/style.css"> tag):

    <!-- @css-start: generated by build.sh (scripts/inline_css.py); never hand-edit -->
    <style>…the rules that can style this page's first screen…</style>
    <link rel="preload" href="/css/style.css?v=<hash>" as="style" onload="this.onload=null;this.rel='stylesheet'">
    <noscript><link rel="stylesheet" href="/css/style.css?v=<hash>"></noscript>
    <!-- @css-end -->

css/style.css is then fetched once and cached for every later page; ?v= changes whenever the bundle does,
so a visitor never pairs new critical CSS with an old cached bundle.

Which rules are critical is worked out from the page itself, not kept by hand. The first screen is the
page's <body> without its <footer>, with <main> cut after its first MAIN_SECTIONS top-level sections, plus
every class name the site's scripts add (js/*.js: the cookie sheet, nav and video states). A rule is kept
when one of its selectors could match there: every class, id and element it names (outside :not()) appears
in that first screen. @font-face is always kept, @media and @supports keep their matching rules, and
@keyframes are kept when a kept rule names them. Everything else arrives with the full bundle, which is
always below the fold when it lands.

Pages that carry no site stylesheet (the destinations/ pages of the private register, which inline
partials/private-register.css.html) are left alone.

    python3 scripts/inline_css.py            # rewrite the pages
    python3 scripts/inline_css.py --report   # sizes only: critical CSS per page, largest first
"""
import hashlib
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
BUNDLE = 'css/style.css'
MAIN_SECTIONS = 3
FIRST_SCREEN_JS = ('consent.js', 'nav.js')
SKIP_DIRS = ('partials', 'graphify-out', 'node_modules', 'command_centre')

START = '  <!-- @css-start: generated by build.sh (scripts/inline_css.py); never hand-edit -->'
END = '  <!-- @css-end -->'
GENERATED = re.compile(r'  <!-- @css-start[^\n]*-->\n.*?  <!-- @css-end -->\n', re.S)
# The build before this script: the whole bundle inlined, or the bare link it restored first.
OLD_INLINE = re.compile(r'  <style>\n    :root \{.*?\n  </style>\n', re.S)
OLD_LINK = re.compile(r'  <link rel="stylesheet" href="[^"]*style\.css">\n')


def pages():
    out = []
    for dirpath, dirnames, filenames in os.walk('.'):
        dirnames[:] = [d for d in dirnames if not d.startswith('.') and d not in SKIP_DIRS]
        out += [os.path.normpath(os.path.join(dirpath, f)) for f in filenames if f.endswith('.html')]
    return sorted(out)


# ── CSS parsing: just enough for this site's hand-written CSS ──

def strip_comments(css):
    return re.sub(r'/\*.*?\*/', '', css, flags=re.S)


def blocks(css):
    """[(prelude, body)] for the top level of css; body is the text inside the braces."""
    out, i, n = [], 0, len(css)
    while i < n:
        j = css.find('{', i)
        if j < 0:
            break
        prelude = css[i:j].strip()
        depth, k = 1, j + 1
        while k < n and depth:
            if css[k] == '{':
                depth += 1
            elif css[k] == '}':
                depth -= 1
            k += 1
        out.append((prelude, css[j + 1:k - 1]))
        i = k
    return out


def split_selectors(prelude):
    parts, depth, cur = [], 0, ''
    for ch in prelude:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
        if ch == ',' and depth == 0:
            parts.append(cur)
            cur = ''
        else:
            cur += ch
    return [p.strip() for p in parts + [cur] if p.strip()]


def needs(selector):
    """(classes, ids, tags) a selector names, ignoring :not(), attributes and pseudo-classes."""
    s = re.sub(r':not\((?:[^()]|\([^()]*\))*\)', '', selector)
    s = re.sub(r'\[[^\]]*\]', '', s)
    s = re.sub(r'::?[\w-]+(\((?:[^()]|\([^()]*\))*\))?', '', s)
    classes = set(re.findall(r'\.(-?[_a-zA-Z][\w-]*)', s))
    ids = set(re.findall(r'#(-?[_a-zA-Z][\w-]*)', s))
    tags = set(t.lower() for t in re.findall(r'(?:^|[\s>+~])([a-zA-Z][\w-]*)', s))
    return classes, ids, tags


def critical(css, inv):
    classes, ids, tags = inv

    def matches(prelude):
        for sel in split_selectors(prelude):
            c, i, t = needs(sel)
            if c <= classes and i <= ids and t <= tags:
                return True
        return False

    def walk(css):
        kept = []
        for prelude, body in blocks(css):
            if prelude.startswith('@font-face'):
                kept.append((prelude, body))
            elif prelude.startswith(('@media', '@supports')):
                inner = walk(body)
                if inner:
                    kept.append((prelude, inner))
            elif prelude.startswith('@keyframes'):
                kept.append((prelude, body))  # filtered below, once the kept rules are known
            elif prelude.startswith('@'):
                continue
            elif matches(prelude):
                kept.append((prelude, body))
        return kept

    kept = walk(css)

    def text(items):
        out = []
        for prelude, body in items:
            if isinstance(body, list):
                out.append(f'{prelude}{{{text(body)}}}')
            else:
                # Declarations only: whitespace runs to one space, none around ':', ';' or ','.
                decl = re.sub(r'\s*([:;,])\s*', r'\1', re.sub(r'\s+', ' ', body.strip()))
                out.append(f'{" ".join(prelude.split())}{{{decl}}}')
        return '\n'.join(out)

    used = text([k for k in kept if not k[0].startswith('@keyframes')])
    kept = [k for k in kept if not k[0].startswith('@keyframes') or k[0].split()[1] in used]
    return text(kept)


# ── What a page's first screen can contain ──

def js_classes():
    """Class names the first-screen scripts add: the cookie sheet and the nav's states. Only these two:
    a class from a script that works further down (video.js's player, say) would bring in a rule such as
    `.video-thumb img{position:absolute}` without its positioned parent, and the image would sit over
    the first screen until the bundle arrived."""
    found = set()
    for name in FIRST_SCREEN_JS:
        src = open(os.path.join('js', name), encoding='utf-8').read()
        for lit in re.findall(r"'([^'\n]*)'|\"([^\"\n]*)\"", src):
            for chunk in lit:
                found |= set(re.findall(r'class="([^"]*)"', chunk.replace('\\"', '"')))
                if re.fullmatch(r'[a-z][\w-]*(?: [a-z][\w-]*)*', chunk):
                    found |= set(chunk.split())
    out = set()
    for f in found:
        out |= set(f.split())
    return out


def first_screen(html):
    body = html.split('<body', 1)[-1]
    body = re.sub(r'<footer\b.*?</footer>', '', body, flags=re.S)
    m = re.search(r'<main\b[^>]*>', body)
    if m:
        rest, depth, count, i = body[m.end():], 0, 0, 0
        for t in re.finditer(r'<(/?)section\b', rest):
            if t.group(1):
                depth -= 1
                if depth == 0:
                    count += 1
                    if count == MAIN_SECTIONS:
                        i = t.end()
                        break
            else:
                depth += 1
        if i:  # keep what follows </main> too: the fixed mobile contact bar sits there
            end = rest.find('</main>', i)
            body = body[:m.end()] + rest[:i] + (rest[end:] if end >= 0 else '')
    return body


def inventory(html, extra):
    screen = first_screen(html)
    classes = set(extra)
    for c in re.findall(r'\bclass="([^"]*)"', screen):
        classes |= set(c.split())
    ids = set(re.findall(r'\bid="([^"]+)"', screen))
    tags = set(t.lower() for t in re.findall(r'<([a-zA-Z][\w-]*)', screen)) | {'html', 'body', 'head'}
    return classes, ids, tags


def block_for(crit, href):
    lines = [START, '  <style>'] + ['    ' + line for line in crit.split('\n')] + ['  </style>',
             f'  <link rel="preload" href="{href}" as="style" onload="this.onload=null;this.rel=\'stylesheet\'">',
             f'  <noscript><link rel="stylesheet" href="{href}"></noscript>', END]
    return '\n'.join(lines) + '\n'


def main(argv):
    report = '--report' in argv
    bundle = open(BUNDLE, encoding='utf-8').read()
    css = strip_comments(bundle)
    href = '/css/style.css?v=' + hashlib.sha256(bundle.encode('utf-8')).hexdigest()[:10]
    extra = js_classes()
    sizes, changed = [], 0
    for f in pages():
        html = open(f, encoding='utf-8').read()
        head, sep, rest = html.partition('</head>')
        if not sep:
            continue
        found = GENERATED.search(head) or OLD_INLINE.search(head) or OLD_LINK.search(head)
        if not found:
            continue
        crit = critical(css, inventory(html, extra))
        sizes.append((len(crit.encode('utf-8')), f))
        new = head[:found.start()] + block_for(crit, href) + head[found.end():] + sep + rest
        if new != html and not report:
            open(f, 'w', encoding='utf-8').write(new)
            changed += 1
    sizes.sort(reverse=True)
    if report:
        for size, f in sizes:
            print(f'{size:7d}  {f}')
    total = len(css.encode('utf-8'))
    big = sizes[0] if sizes else (0, '-')
    print(f'Critical CSS in {len(sizes)} pages (largest {big[0] // 1024} KB, {big[1]}; the bundle is '
          f'{total // 1024} KB); {changed} pages rewritten')
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
